/* Service wizard uses typed values; users never enter HAProxy directives. */
(() => {
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=value=>JSON.parse(JSON.stringify(value));
const check=value=>value?' checked':'';
const selected=(a,b)=>a===b?' selected':'';
let view,data,actions,model,step;
function preset(){return data.presets.find(p=>p.id===model.protocol)}
function web(){return preset().kind==='http'}
function control(name,label,value,extra='',help=''){return `<div class="field"><label for="service-${name}">${label}</label><input id="service-${name}" name="${name}" value="${esc(value)}" ${extra}>${help?`<span class="field-help">${help}</span>`:''}</div>`}
function select(name,label,value,options,help=''){return `<div class="field"><label for="service-${name}">${label}</label><select id="service-${name}" name="${name}"${name==='certificate'?' required':''}${name==='protocol'&&model?.imported||name==='health'&&model?.http_action==='redirect'?' disabled':''}>${options.map(([id,text])=>`<option value="${esc(id)}"${selected(id,value)}>${esc(text)}</option>`).join('')}</select>${help?`<span class="field-help">${help}</span>`:''}</div>`}
function toggle(name,label,value,help=''){return `<label class="toggle-field"><input type="checkbox" name="${name}"${check(value)}><span><strong>${label}</strong>${help?`<span class="field-help">${help}</span>`:''}</span></label>`}
function defaults(protocol='https'){const p=data.presets.find(p=>p.id===protocol);return {naming:'readable',name:'',protocol,enabled:true,domain:'',path:'/',port:p.port,bind_address:'*',tls_mode:p.tls,certificate:'',redirect:p.tls==='terminate',http_port:80,backends:[{host:'',port:p.backend_port,weight:1,backup:false}],balance:'roundrobin',health:'tcp',health_path:'/',upstream_tls:false,upstream_verify:true,upstream_name:'',allowed_ips:'',host_override:'',strip_prefix:false,hsts:false,timeout:3600,check_interval:5,maxconn:0,proxy_protocol:false,...enterpriseDefaults(protocol),...(protocol==='studio'?{name:'HAProxy Studio',path:data.studio?.base_path||'/haproxy-admin',root_redirect:(data.studio?.base_path||'/haproxy-admin')+'/',redirect_root:true,canonical_slash:true,update_public_url:false,health:'http',health_path:(data.studio?.base_path||'/haproxy-admin')+'/api/health',backends:[{host:({'0.0.0.0':'127.0.0.1','::':'::1'}[data.studio?.bind]||data.studio?.bind||'127.0.0.1'),port:data.studio?.port||9130,weight:1,backup:false}]}:protocol==='rdwebproxy'?{rdweb_client:'standard',upstream_tls:true,health:'http',health_path:'/RDWeb/',root_redirect:'/RDWeb/',redirect_root:true,balance:'source'}:{}),...(protocol==='rds'?{rds_mode:'broker',balance:'leastconn',timeout:28800}:['rdgateway','rdweb'].includes(protocol)?{sni_routing:true,balance:'source',rdweb_client:protocol==='rdweb'?'standard':'none',timeout:protocol==='rdgateway'?28800:3600}:{})}}
function endpoint(m){if(m.protocol==='rdwebproxy')return 'https://'+m.domain+(Number(m.port)===443?'':':'+m.port)+rdwebPath(m);if(m.sni_routing&&!['rdgateway','rdweb'].includes(m.protocol)){const host=(m.domains||[])[0];if(host)return host+':'+m.port+' (SNI)'}if(['rdgateway','rdweb'].includes(m.protocol)){const host=(m.domains?.length?m.domains:String(m.sni_domains||'').split(/[\s,;]+/).filter(Boolean))[0];if(host)return 'https://'+host+(Number(m.port)===443?'':':'+m.port)+rdwebPath(m)}return m.domain?(m.tls_mode==='terminate'?'https://':'http://')+m.domain+((m.port==443&&m.tls_mode==='terminate'||m.port==80&&m.tls_mode==='plain')?'':':'+m.port)+(m.path==='/'?'':m.path):(m.bind_address==='*'?'Адрес сервера':m.bind_address)+':'+m.port}
function status(m){return data.service_status?.[m.id]||(!m.enabled?'Выключен':m.http_action==='redirect'?'Перенаправление настроено':'Ожидание данных')}
function statusClass(m){const label=status(m);return label==='Сервер доступен'?' good':label==='Сервер недоступен'?' bad':''}
function routeStatus(m){const rows=(data.route_runtime||{})[m.id]||[];return rows.length?'<details class="route-health"><summary>Проверки служб</summary>'+rows.map(r=>'<p>'+esc(r.path)+' — '+(r.action==='deny'?'Закрыт (403)':!r.rows.length?'Ожидание данных':r.rows.some(n=>n.status==='UP')?'Доступен':'Недоступен')+'</p>').join('')+'</details>':''}
function list(){model=null;actions.dirty(false);view.innerHTML=`<section class="panel"><div class="panel-heading"><div><h2>Сервисы</h2><p>Добавляйте и изменяйте сервисы без знания конфигурации HAProxy.</p></div><div class="service-actions"><button data-service-action="names"${data.read_only?' disabled':''}>Понятные имена в конфиге</button><button data-service-action="import"${data.read_only?' disabled':''}>Импортировать конфиг</button><button class="primary" data-service-action="new"${data.read_only?' disabled':''}>Добавить сервис</button></div></div>${diagnosticNotice()}${data.read_only?'<p class="read-only-note">Установка работает в режиме наблюдения. Публикация отключена.</p>':''}${data.services.length?`<div class="service-list">${data.services.map(m=>`<article class="service-item"><div class="service-name"><h3>${esc(m.name)}</h3><span class="badge${statusClass(m)}">${esc(status(m))}</span><p>${esc(data.presets.find(p=>p.id===m.protocol)?.label||m.protocol)}</p></div><div class="service-destination"><strong class="mono">${esc(endpoint(m))}</strong><span>${esc(m.backends.map(b=>b.host+':'+b.port).join(', '))}</span>${m.import_pool?'<span>Импорт ACL · общий backend '+esc(m.import_pool)+'</span>':''}${routeStatus(m)}</div><div class="service-actions">${m.import_pool&&m.import_pool_id?`<button data-service-action="shared-pool" data-id="${m.id}" title="${esc(m.import_pool_blocked||'Изменить адреса общих серверов')}"${data.read_only||m.import_pool_blocked?' disabled':''}>Общий пул</button>`:''}<button data-service-action="edit" data-id="${m.id}"${data.read_only?' disabled':''}>Изменить</button><button data-service-action="toggle" data-id="${m.id}"${data.read_only?' disabled':''}>${m.enabled?'Выключить':'Включить'}</button><button class="danger-link" data-service-action="delete" data-id="${m.id}"${data.read_only?' disabled':''}>Удалить</button></div></article>`).join('')}</div>`:'<div class="service-empty"><h3>Опубликуйте первый сервис</h3><p>Выберите протокол, укажите адрес внутреннего сервера и проверьте настройки. Панель создаст правила, сохранит копию и плавно перезагрузит HAProxy.</p></div>'}</section>${manualServices()}<div class="service-notes"><p>Ручные публикации показаны выше и в разделе «Маршруты и серверы». Для переноса поддерживаемых правил в «Сервисы» нажмите «Импортировать конфиг».</p><p>После публикации DNS домена должен указывать на этот сервер. Внешний порт должен быть разрешён в сети и у провайдера.</p></div>`}
function manualPool(id,entry){const item=entry||data.discovered_services.find(m=>m.id===id),d=document.createElement('dialog');d.className='admin-dialog';d.setAttribute('aria-label','Адреса серверов '+item.name);d.innerHTML=`<form><h2>${esc(item.name)}</h2><p>Частичное управление: изменятся только адрес и порт. TLS, проверки, ACL, балансировка и комментарии сохраняются. Изменение общего пула затронет все связанные публикации.</p>${item.servers.map((s,i)=>{const match=s.address.match(/^(\[[^\]]+\]|[^:]+):(\d+)$/);return `<fieldset><legend>${esc(s.name)}</legend><label class="field">Адрес<input name="host${i}" value="${esc(match?.[1].replace(/^\[|\]$/g,'')||'')}" required></label><label class="field">Порт<input name="port${i}" type="number" min="1" max="65535" value="${esc(match?.[2]||'')}" required></label></fieldset>`}).join('')}<p class="error" role="alert" data-error></p><div class="dialog-actions"><button type="button" data-cancel>Отмена</button><button class="primary">Проверить изменения</button></div></form>`;document.body.append(d);d.onclose=()=>d.remove();d.querySelector('[data-cancel]').onclick=()=>d.close();d.querySelector('form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{try{const values=new FormData(e.target),result=await actions.api('backends/preview-edit',{id:item.pool_id,revision:data.revision,servers:item.servers.map((s,i)=>({name:s.name,host:values.get('host'+i),port:values.get('port'+i)}))});d.close();actions.review(result)}catch(error){d.querySelector('[data-error]').textContent=error.message}})};d.showModal()}
function diagnosticNotice(){const d=data.diagnostic;if(!d?.validation)return '';return `<details class="advanced-options"${d.validation.ok?'':' open'}><summary>Проверка исходной конфигурации: ${d.validation.ok?'пройдена':'обнаружены ошибки'}</summary><p>${esc(d.ssl_library)}</p><pre>${esc(d.validation.output)}</pre>${(d.ssl_issues||[]).map(i=>`<p>Строка ${i.line}: ${esc(i.message)}</p>`).join('')}${d.ssl_issues?.length?'<button data-service-action="compatibility">Просмотреть исправление настроек DH</button>':''}</details>`}
function manualServices(){const groups=new Map(),rows=[];for(const item of data.discovered_services||[]){if(item.infrastructure)continue;if(!item.exchange){rows.push(item);continue}const key=item.frontend+'|'+item.servers.map(s=>s.address).sort().join(',');let group=groups.get(key);if(!group){group={...item,name:'Exchange · '+(item.domains[0]||item.backend),members:[]};groups.set(key,group);rows.push(group)}group.members.push(item);if(group.members.some(x=>x.status==='Сервер недоступен'))group.status='Есть недоступные службы'}if(!rows.length)return '';return `<section class="panel"><div class="panel-heading"><div><h2>Обнаружены в конфигурации</h2><p>Работают по существующим правилам. Просмотр не меняет конфигурацию; для переноса используйте импорт.</p></div></div><div class="service-list">${rows.map(m=>`<article class="service-item"><div class="service-name"><h3>${esc(m.name)}</h3><span class="badge">${m.editable?'Частичное управление':'Ручная публикация'}</span><p>${esc(m.status)}</p></div><div class="service-destination"><strong>${esc(m.domains.join(', ')||m.frontend)}</strong><span>${esc(m.servers.map(s=>s.address).join(', '))}</span>${m.members?`<details><summary>Службы Exchange · ${m.members.length}</summary>${m.members.map(child=>`<p><strong>${esc(child.health_path.replace(/\/healthcheck\.htm$/i,''))}</strong> · ${esc(child.backend)} · ${esc(child.status)} ${child.editable&&!data.read_only?`<button data-service-action="manual-pool" data-id="${child.id}">Изменить серверы</button>`:''}</p>`).join('')}</details>`:''}<details><summary>Связанные правила</summary><p>Вход: ${esc(m.frontend)} · порты ${esc(m.ports.join(', '))}</p><p>Backend: ${esc(m.backend)} · ${esc(m.source||'haproxy.cfg')} · строка ${esc(m.line)}</p><p>${esc(m.condition||'По умолчанию')}</p></details></div><div class="service-actions">${m.editable&&!m.members&&!data.read_only?`<button data-service-action="manual-pool" data-id="${m.id}">Изменить адреса серверов</button>`:''}<a class="button-link" href="#config">Открыть конфигурацию</a></div></article>`).join('')}</div></section>`}
function capture(){const form=view.querySelector('#service-form');if(!form)return;const values=new FormData(form);for(const name of ['import_domain_template','rdweb_client','replacement_id','naming','backend_name','http_redirect_mode','https_frontend','tunnel_timeout','redirect_code','http_host_match','http_redirect_location','http_action','health_http_version','health_host','health_tls_name','cookie_name','upstream_tls_version','fallback_status','rds_mode','name','protocol','domain','path','port','bind_address','tls_mode','certificate','http_port','balance','health','health_path','upstream_name','allowed_ips','host_override','timeout','check_interval','maxconn','aliases','sni_domains','root_redirect','http_exceptions','health_status','health_method','smtp_ehlo','check_rise','check_fall'])if(values.has(name))model[name]=values.get(name);for(const name of ['update_public_url','replacement_confirm','replacement_keep_redirect','http_redirect_all_paths','forward_headers','backend_forwardfor','upstream_sni','health_tls_verify','health_send_proxy','redirect_root','canonical_slash','reject_other_paths','enabled','redirect','strip_prefix','upstream_tls','upstream_verify','hsts','proxy_protocol','sni_routing','sni_default','path_ignore_case','security_headers','health_log'])if(form.elements.namedItem(name))model[name]=form.elements.namedItem(name).checked;if(form.querySelector('[name=certificates]'))model.certificates=[...form.querySelector('[name=certificates]').selectedOptions].map(o=>o.value);captureRoutes(form);if(form.querySelector('[data-backend-row]'))model.backends=[...form.querySelectorAll('[data-backend-row]')].map((row,i)=>({...model.backends[i],name:row.querySelector('[data-server-name]')?row.querySelector('[data-server-name]').value:model.backends[i]?.name||'',cookie_value:row.querySelector('[data-cookie]')?.value||model.backends[i]?.cookie_value||'',host:row.querySelector('[data-host]').value,port:row.querySelector('[data-port]').value,weight:row.querySelector('[data-weight]').value,backup:row.querySelector('[data-backup]').checked}));}
function rdwebPath(m){return {standard:'/RDWeb/',html5:'/RDWeb/webclient/',none:''}[m.rdweb_client||(['rdweb','rdwebproxy'].includes(m.protocol)?'standard':'none')]||''}
function rdwebChoice(){if(!['rdweb','rdgateway','rdwebproxy'].includes(model.protocol))return '';const options=[['standard','Обычный портал — /RDWeb/'],['html5','HTML5-клиент — /RDWeb/webclient/']];if(model.protocol==='rdgateway')options.unshift(['none','Только адрес шлюза — без пути портала']);return select('rdweb_client',model.protocol==='rdweb'?'Какая страница RD Web нужна?':'RD Web на общем домене шлюза',model.rdweb_client||(['rdweb','rdwebproxy'].includes(model.protocol)?'standard':'none'),options,model.protocol==='rdwebproxy'?'HAProxy перенаправляет GET и HEAD с корня / на выбранную страницу. Остальные запросы передаются IIS.':'Путь добавляется в адрес открытия портала. При сквозном TLS перенаправление корня сайта настраивается в IIS.') }
function first(){return `<h2>Что хотите опубликовать?</h2><p>Выберите готовый шаблон. Панель подставит обычные порты и подходящий способ передачи данных.</p>${control('name','Название сервиса',model.name,'required maxlength="80" placeholder="Например: Рабочий стол офиса"')}${select('protocol','Тип сервиса',model.protocol,data.presets.map(p=>[p.id,p.label]))}${rdwebChoice()}${model.imported?'<p class="field-help">Импортированная публикация: тип сохранён для совместимости с текущими правилами.</p>':''}<div class="protocol-description"><strong>${esc(preset().label)}</strong><p>${esc(preset().description)}</p><span class="small">Обычные порты: снаружи ${preset().port} → сервер ${preset().backend_port}. Их можно изменить.</span></div>`}
function security(){let html='';if(['smtps','imaps','pop3s','tls'].includes(model.protocol))html+=select('tls_mode','Где обрабатывается TLS?',model.tls_mode,[['passthrough','На внутреннем сервере — сквозной TLS'],['terminate','На HAProxy — выбрать или загрузить сертификат']]);if(model.tls_mode==='terminate'){html+=select('certificate','Сертификат для подключения клиентов',model.certificate,[['','Выберите сертификат'],...data.certificates.map(c=>[c.name,c.label||c.name])],'Сертификат должен покрывать домен сайта и соответствовать приватному ключу.');html+=extraCertificates();html+=`<details class="upload-details"><summary>Загрузить новый сертификат</summary><div class="upload-fields"><div class="field"><label for="certificate-label">Название сертификата</label><input id="certificate-label" maxlength="80" placeholder="Например: Сертификат сайта"></div><div class="field"><label for="certificate-file">Сертификат PEM / CRT или контейнер PFX / P12</label><input id="certificate-file" type="file" accept=".pem,.crt,.cer,.pfx,.p12,.txt"></div><div class="field"><label for="certificate-key">Приватный ключ KEY / PEM</label><input id="certificate-key" type="file" accept=".pem,.key,.txt"><span class="field-help">Если ключ уже находится в файле PEM, отдельный файл не нужен.</span></div><div class="field"><label for="certificate-chain">Промежуточные сертификаты — CA Bundle (необязательно)</label><input id="certificate-chain" type="file" accept=".pem,.crt,.cer,.txt"><span class="field-help">Если fullchain уже в PEM или PFX, дополнительный файл не нужен.</span></div><div class="field"><label for="certificate-password">Пароль ключа или PFX/P12, если задан</label><input id="certificate-password" type="password" autocomplete="off"></div><button type="button" data-service-action="upload">Проверить и сохранить сертификат</button><p class="field-help">Текстовые PEM/CRT и KEY, до 512 КБ каждый. Поддерживаются также PFX/P12 с ключом и цепочкой. DER сначала преобразуйте в PEM. Приватный ключ не возвращается браузеру.</p></div></details>`}else if(!web())html+='<p class="field-help">'+esc(preset().description)+'</p>';return html}
function backendRows(){return model.backends.map((server,i)=>`<fieldset class="backend-row" data-backend-row><legend>Внутренний сервер ${i+1}</legend><div class="backend-fields"><div class="field"><label for="backend-name-${i}">Имя сервера в конфиге</label><input id="backend-name-${i}" data-server-name maxlength="63" value="${esc(server.name||'')}" placeholder="srv_web01"><span class="field-help">При понятных именах пустое поле формируется из IP/домена и порта.</span></div><div class="field"><label for="backend-host-${i}">IP или домен</label><input id="backend-host-${i}" data-host value="${esc(server.host)}" required placeholder="192.168.1.50"></div><div class="field"><label for="backend-port-${i}">Порт</label><input id="backend-port-${i}" data-port type="number" min="1" max="65535" value="${esc(server.port)}" required></div><div class="field"><label for="backend-weight-${i}">Вес</label><input id="backend-weight-${i}" data-weight type="number" min="1" max="256" value="${esc(server.weight)}" required></div>${model.cookie_name?`<div class="field"><label for="backend-cookie-${i}">Cookie сервера</label><input id="backend-cookie-${i}" data-cookie value="${esc(server.cookie_value||'node'+(i+1))}" required maxlength="64"></div>`:''}</div><div class="backend-options"><label><input type="checkbox" data-backup${check(server.backup)}> Резервный сервер</label><button type="button" data-service-action="remove-backend" data-index="${i}"${model.backends.length===1?' disabled':''}>Убрать сервер ${i+1}</button></div></fieldset>`).join('')}
function sharedSecond(){return `<h2>Домены общего пула</h2><p>Маршруты импортированы с сохранением исходного порядка. Backend <strong>${esc(model.import_pool)}</strong>, TLS, проверки и остальные политики остаются в конфигурации.</p><p>Вход: ${esc(model.import_acl.frontend)} · порт ${esc(model.port)}</p>${web()?control('domain','Основной домен',model.domain,'required')+textarea('aliases','Другие домены этого пула',model.aliases,'По одному домену в строке. Изменение относится к импортированным backend-маршрутам; отдельные правила редиректов и доступа frontend сохраняются.'):textarea('sni_domains','Домены SNI общего пула',model.domains||model.sni_domains,'Все эти домены направляются в один существующий backend.')}${select('import_domain_template','Как обрабатывать добавленные домены',model.import_domain_template||'',[['','Автоматически — если дополнительные ACL одинаковые'],...[...new Set(model.import_acl.slots.flatMap(s=>s.terms.flatMap(t=>t.domains)))].map(d=>[d,'Как '+d])],'Если у доменов разные правила путей или доступа, выберите существующий домен как образец. Его дополнительные ACL будут применяться к добавленным доменам.')}<h3>Общие серверы</h3><p>${esc(model.backends.map(s=>s.host+':'+s.port).join(', '))}</p><p class="field-help">Адреса серверов меняются кнопкой «Общий пул» в списке сервисов. Изменение затронет все публикации, которые используют этот backend.</p>`}
function sharedThird(){return `<h2>Проверьте импортированные маршруты</h2><div class="publication-summary"><h3>${esc(model.name)}</h3><p>Общий backend: ${esc(model.import_pool)}</p><p>Вход: ${esc(model.import_acl.frontend)} · порт ${esc(model.port)}</p><p>Домены: ${esc((web()?[model.domain,...(Array.isArray(model.aliases)?model.aliases:String(model.aliases||'').split(/[\s,;]+/))]:model.domains||[]).filter(Boolean).join(', '))}</p><p>Исходных правил: ${model.import_acl.slots.length}. Пул не копируется; его параметры сохраняются.</p></div><p>Добавленные домены будут обрабатываться ${esc(model.import_domain_template?'по образцу '+model.import_domain_template:'автоматически, если дополнительные ACL одинаковые')}. Исходные правила frontend и общий backend сохраняются.</p>${toggle('enabled','Включить маршруты этой публикации',model.enabled,'Отключение убирает только эти маршруты. Общий backend, другие правила frontend и default_backend сохраняются и могут продолжить обработку запросов.')}`}
function second(){if(model.import_pool)return sharedSecond();return `<h2>Адреса и защита</h2><p>Снаружи — адрес для пользователей. Внутри — сервер, на котором уже работает приложение.</p><div class="wizard-section"><h3>Имена в конфигурации</h3>${select('naming','Как называть backend и серверы',model.naming||'legacy',[['readable','Понятные имена'],['legacy','Прежние технические имена']])}${control('backend_name','Имя основного backend',model.backend_name||'','maxlength="63" placeholder="be_website"','При понятных именах пустое поле формируется из названия сервиса. Латинские буквы, цифры, _, точка и дефис.')}</div><div class="wizard-section"><h3>Публичный адрес</h3>${StudioPreserve.action(model)}${web()?control('domain','Домен сайта',model.domain,'required placeholder="app.example.org" autocomplete="off"','Только имя домена, без https://, порта и пути. Можно использовать международное имя.'):''}${domainFields()}<div class="form-grid">${control('port','Внешний TCP-порт',model.port,'type="number" min="1" max="65535" required')}${control('bind_address','На каком IP принимать подключения',model.bind_address,'required','* — на всех IPv4-адресах сервера; можно указать отдельный IPv4 или IPv6.')}</div>${web()?control('path','Путь сайта',model.path,'required placeholder="/"','/ — весь домен; /app — только этот путь и его подпути.')+toggle('strip_prefix','Убирать префикс пути перед передачей серверу',model.strip_prefix,'Например, /app/page станет /page. При пути / настройка не нужна.'):''}</div><div class="wizard-section"><h3>Шифрование подключения</h3>${sniFields()}${security()}${StudioPreserve.listener(model,data)}${(web()&&model.tls_mode==='terminate'||['rdgateway','rdweb'].includes(model.protocol)&&model.sni_routing)?toggle('redirect',['rdgateway','rdweb'].includes(model.protocol)&&rdwebPath(model)?'Перенаправлять HTTP на страницу портала':'Перенаправлять HTTP на HTTPS',model.redirect,['rdgateway','rdweb'].includes(model.protocol)?'Запросы по HTTP будут перенаправлены на выбранный HTTPS-адрес. Для корня уже открытого HTTPS-сайта нужен редирект IIS.':'Пользователи с http:// автоматически попадут на защищённый адрес.')+(model.redirect?control('http_port','Порт входящего HTTP',model.http_port,'type="number" min="1" max="65535" required','Обычно 80. Для HTTPS останется указанный выше внешний порт.'):''):''}</div>${web()?webRoutingFields():''}${model.http_action==='redirect'?'':`<div class="wizard-section"><h3>${['rdgateway','rdweb'].includes(model.protocol)?(model.protocol==='rdgateway'?'Серверы Windows RD Gateway':'Серверы Windows RD Web / IIS'):model.protocol==='rds'?(model.rds_mode==='token'?'Серверы фермы Session Host':'RDP-вход брокера / redirector'):'Куда передавать подключения'}</h3>${rdsFields()}${remoteHttpsNotice()}${backendRows()}<button type="button" data-service-action="add-backend"${model.backends.length>=16?' disabled':''}>Добавить ещё сервер</button>${model.tls_mode!=='passthrough'&&model.protocol!=='rds'?toggle('upstream_tls','Внутренний сервер тоже использует TLS',model.upstream_tls,'Для HTTPS-сервера обычно нужен порт 443. Не включайте для обычного HTTP, RDP или STARTTLS.')+(model.upstream_tls?toggle('upstream_sni','Передавать TLS-имя серверу (SNI)',model.upstream_sni!==false,'Оставьте выключенным, если старая публикация работала без SNI.')+toggle('upstream_verify','Проверять сертификат внутреннего сервера',model.upstream_verify,'Используются системные доверенные CA. Отключайте только для осознанного подключения к доверенному серверу с самоподписанным сертификатом.')+(model.upstream_sni!==false?control('upstream_name','TLS-имя внутреннего сервера',model.upstream_name,'placeholder="app.example.org"','Имя для SNI и проверки сертификата. По умолчанию — публичный домен или имя первого сервера.'):''):''):''}</div>`}`}
function replacementChoice(){if(model.id||!['rdgateway','rdweb'].includes(model.protocol))return '';const domains=model.domains?.length?model.domains:String(model.sni_domains||'').split(/[\s,;]+/).filter(Boolean),normalized=domains.map(d=>String(d).toLowerCase().replace(/\.$/,'')),matches=data.services.filter(s=>s.enabled&&s.port==model.port&&['http','https','websocket','exchange'].includes(s.protocol)&&(s.domains||[s.domain]).some(d=>normalized.includes(d)));if(!matches.some(s=>s.id===model.replacement_id)){model.replacement_id='';model.replacement_confirm=false}if(!matches.length)return '';const target=matches.find(s=>s.id===model.replacement_id);return `<section class="wizard-section"><h3>Этот адрес уже опубликован</h3><p>На этом домене и порту уже настроен веб-сервис. Для RD Gateway можно заменить его одной операцией. Сначала панель покажет полную разницу конфигурации.</p>${select('replacement_id','Какую публикацию заменить',model.replacement_id||'',[['','Создать отдельно — указать другой домен'],...matches.map(s=>[s.id,s.name])])}${target?`<p class="field-help">Будет заменён сервис: <strong>${esc(target.name)}</strong> · ${esc((target.domains||[target.domain]).join(', '))}:${target.port}</p>`:''}${toggle('replacement_confirm','Подтверждаю замену выбранной публикации на RD Gateway / RD Web',!!model.replacement_confirm,'Старые HTTP-правила и ограничения путей не переносятся в сквозной TLS. Сертификат и права доступа должны быть настроены на Windows.')}${toggle('replacement_keep_redirect','Сохранить существующее HTTP-перенаправление',model.replacement_keep_redirect!==false)}</section>`}
function selfPublicationNotice(){const b=model.backends[0],local=['127.0.0.1','localhost','::1'];if(model.protocol==='studio'||!web()||model.backends.length!==1||Number(b.port)!==Number(data.studio?.port)||!(b.host===data.studio?.bind||local.includes(b.host)&&[...local,'0.0.0.0','::'].includes(data.studio?.bind)))return '';return '<section class="wizard-section"><h3>Обнаружена сама панель Studio</h3><p>Для этой публикации нужно согласовать base_path и public_url, чтобы проверки адреса не заблокировали вход.</p><button type="button" data-service-action="self-preset">Настроить как публикацию этой панели</button></section>'}
function third(){if(model.import_pool)return sharedThird();return `<h2>Проверьте публикацию</h2><p>Панель сначала проверит конфликты и конфигурацию. Изменения вступят в силу только после вашего подтверждения.</p><div class="publication-summary"><h3>${esc(model.name)}</h3><dl class="summary-list"><dt>Тип</dt><dd>${esc(preset().label)}</dd><dt>Подключение пользователей</dt><dd class="mono">${esc(endpoint(model))}</dd><dt>Внутренние серверы</dt><dd>${model.backends.length?model.backends.map(b=>`<span class="mono">${esc(b.host)}:${esc(b.port)}${b.backup?' · резервный':''}</span>`).join('<br>'):'Не используются — только перенаправление'}</dd><dt>Шифрование</dt><dd>${model.tls_mode==='terminate'?'Сертификат на HAProxy':model.tls_mode==='passthrough'?'TLS на внутреннем сервере':'Нативный протокол без изменения'}</dd>${model.redirect?'<dt>HTTP → HTTPS</dt><dd>Включено: порт '+esc(model.http_port)+' → '+esc(model.port)+'</dd>':''}</dl></div>${replacementChoice()}${selfPublicationNotice()}${model.protocol==='studio'?toggle('update_public_url','Обновить публичный адрес самой панели после применения',model.update_public_url,'public_url будет содержать только https://домен и порт; base_path сохраняется отдельно. После применения войдите по новому адресу. При ошибке reload адрес не меняется.'):''}${enterpriseSummary()}${remoteHttpsNotice()}${model.protocol==='rds'?rdsNotice():''}${model.http_action==='redirect'?'':`<button type="button" data-service-action="check">Проверить доступность внутренних серверов</button><div id="connectivity-results" role="status"></div>`}<details class="advanced-options"><summary>Дополнительные настройки</summary><div class="advanced-fields">${select('balance','Распределение между серверами',model.balance,[['roundrobin','По очереди — для большинства сервисов'],['leastconn','На менее занятый сервер — для долгих соединений'],['source','По IP клиента — сохранять выбор сервера']])}${select('health','Автоматическая проверка сервера',model.health,[['tcp','Проверять соединение с портом'],...(web()?[['http','Проверять HTTP-страницу']]:['rds','rdgateway','rdweb'].includes(model.protocol)?[]:[['tls','Проверять TLS-рукопожатие (без проверки CA)']]),...(['smtp','submission','smtps'].includes(model.protocol)?[['smtp','Проверять SMTP: EHLO и ответ сервера']]:[]),['none','Без проверок']])}${web()&&model.health==='http'?control('health_path','Страница проверки',model.health_path,'placeholder="/health"','Ответ 2xx или 3xx считается успешным.'):''}<div class="field"><label for="service-allowed_ips">Разрешённые IP клиентов</label><textarea id="service-allowed_ips" name="allowed_ips" rows="3" placeholder="192.0.2.10, 198.51.100.0/24">${esc(model.allowed_ips)}</textarea><span class="field-help">Пусто — доступ всем. Можно перечислить IP через запятую или сети CIDR. Для RDP, SSH и баз данных рекомендуется ограничить доступ.</span></div>${healthFields()}<div class="form-grid">${control('timeout','Таймаут соединения, секунд',model.timeout,'type="number" min="5" max="86400"')}${control('check_interval','Интервал проверки, секунд',model.check_interval,'type="number" min="1" max="300"')}${control('maxconn','Лимит соединений на сервер',model.maxconn,'type="number" min="0" max="100000"','0 — не задавать отдельный лимит.')}</div>${web()?control('host_override','Подменять HTTP-заголовок Host',model.host_override,'placeholder="Оставить исходный"','Нужно только если внутренний сайт ожидает другое доменное имя.')+ (model.tls_mode==='terminate'?toggle('hsts','Включить HSTS для домена',model.hsts,'Браузер будет требовать HTTPS в течение года. Включайте после проверки сертификата и доступности сайта.'):''):''}${['rds','rdgateway','rdweb'].includes(model.protocol)?'':toggle('proxy_protocol','Передавать PROXY protocol v2 внутреннему серверу',model.proxy_protocol,'Включайте только если сервер явно настроен принимать PROXY protocol. Иначе подключения перестанут работать.')}${toggle('enabled','Включить публикацию после применения',model.enabled,'Если выключено, настройки сохранятся, но внешний вход не создаётся.')}</div></details>${StudioPreserve.fields(model)}<div class="publication-checklist"><strong>Что ещё должно быть готово</strong><ul><li>Внутреннее приложение запущено и доступно серверу HAProxy.</li>${web()?'<li>DNS-запись домена указывает на публичный адрес этого сервера.</li>':''}<li>Внешний TCP-порт разрешён на маршрутизаторе и в firewall провайдера.</li></ul><p class="field-help">HAProxy публикует уже работающий сервис. Мастер не устанавливает RDP, почтовый сервер или базу данных и не меняет DNS у регистратора.</p></div>`}
function wizard(focus=true){view.innerHTML=`<div class="wizard-top"><button data-service-action="cancel">К списку сервисов</button><span class="small">${model.id?'Изменение публикации':'Новая публикация'}</span></div><ol class="wizard-progress" aria-label="Этапы настройки">${['Тип сервиса','Адреса и защита','Проверка'].map((label,i)=>`<li${step===i?' aria-current="step"':''}><span>${i+1}</span>${label}</li>`).join('')}</ol><section class="panel wizard-panel"><form id="service-form" class="wizard-form" novalidate><div id="service-error" class="notice error" role="alert" tabindex="-1" hidden></div>${[first,second,third][step]()}<div class="wizard-actions">${step?'<button type="button" data-service-action="back">Назад</button>':'<span></span>'}<button type="submit" class="primary">${step===2?'Проверить и опубликовать':'Продолжить'}</button></div></form></section>`;if(focus)view.querySelector('h2').setAttribute('tabindex','-1'),view.querySelector('h2').focus();}
function error(message){const box=view.querySelector('#service-error');if(box){box.hidden=false;box.textContent=message;box.focus()}else actions.notify(message,true)}
function valid(){const form=view.querySelector('#service-form');const invalid=[...form.querySelectorAll('input,select,textarea')].find(el=>!el.checkValidity());if(invalid){let ancestor=invalid.parentElement;while(ancestor){if(ancestor.tagName==='DETAILS')ancestor.open=true;ancestor=ancestor.parentElement}invalid.reportValidity();return false}return true}
async function run(button,fn){if(button.disabled)return;button.disabled=true;const text=button.textContent;button.textContent='Проверяем…';try{await fn()}catch(e){error(e.message)}finally{if(button.isConnected){button.disabled=false;button.textContent=text}}}
async function handleClick(event){const button=event.target.closest('[data-service-action]');if(!button)return;const action=button.dataset.serviceAction;if(action==='shared-pool'){const m=data.services.find(s=>s.id===button.dataset.id);manualPool(null,{name:m.import_pool,pool_id:m.import_pool_id,servers:m.backends.map(s=>({name:s.name,address:(s.host.includes(':')?'['+s.host+']':s.host)+':'+s.port}))});return}if(action==='self-preset'){const old=model;model={...defaults('studio'),id:old.id,name:old.name,domain:old.domain,certificate:old.certificate,port:old.port,http_port:old.http_port,https_frontend:old.https_frontend};step=1;wizard();return}if(action==='manual-pool'){manualPool(button.dataset.id);return}if(action==='compatibility')return run(button,async()=>actions.review(await actions.api('compatibility/preview',{revision:data.revision})));if(action==='names')return run(button,async()=>actions.review(await actions.api('services/names/preview',{revision:data.revision})));if(action==='import'){window.StudioImport.mount(view,data,actions,()=>mount(view,data,actions));return}if(['new','edit'].includes(action)){model=action==='new'?defaults():clone(data.services.find(s=>s.id===button.dataset.id));step=0;actions.dirty(false);wizard();return}if(action==='cancel'){capture();if(model&&(!model.name&&!model.backends[0].host||confirm('Закрыть мастер без публикации изменений?')))list();return}if(action==='delete'||action==='toggle'){const target=data.services.find(s=>s.id===button.dataset.id);return run(button,async()=>actions.review(await actions.api('services/preview',{revision:data.revision,action:action==='delete'?'delete':'upsert',service:action==='delete'?{id:target.id}:{...target,enabled:!target.enabled}})))}capture();if(action==='add-route'){model.routes=model.routes||[];model.routes.push({path:'',action:'backend',health_path:'/',health_status:'200',timeout:model.timeout,balance:model.balance,backends:[],inherit_pool:true});wizard(false);actions.dirty(true);return}if(action==='remove-route'){model.routes.splice(Number(button.dataset.index),1);wizard(false);actions.dirty(true);return}if(action==='back'){step--;wizard();return}if(action==='add-backend'){model.backends.push({host:'',port:preset().backend_port,weight:1,backup:false});wizard(false);actions.dirty(true);return}if(action==='remove-backend'){model.backends.splice(Number(button.dataset.index),1);wizard(false);actions.dirty(true);return}if(action==='check'){return run(button,async()=>{const result=await actions.api('services/check',{service:model});view.querySelector('#connectivity-results').innerHTML=result.results.map(r=>`<p class="${r.ok?'':'error'}"><strong>${esc(r.host)}:${r.port}</strong> — ${esc(r.message)}</p>`).join('')+`<p class="field-help">${esc(result.note)}</p>`})}if(action==='upload'){return run(button,async()=>{const cert=view.querySelector('#certificate-file').files[0],key=view.querySelector('#certificate-key').files[0];if(!cert)throw Error('Выберите PEM/CRT-сертификат.');if(cert.size>524288||key&&key.size>524288)throw Error('Каждый файл должен быть не больше 512 КБ.');const result=await actions.api('certificates/upload',{certificate:/\.(pfx|p12)$/i.test(cert.name)?'':await cert.text(),pfx_base64:/\.(pfx|p12)$/i.test(cert.name)?btoa(Array.from(new Uint8Array(await cert.arrayBuffer()),b=>String.fromCharCode(b)).join('')):'',key:key?await key.text():'',ca_bundle:view.querySelector('#certificate-chain').files[0]?await view.querySelector('#certificate-chain').files[0].text():'',password:view.querySelector('#certificate-password').value,label:view.querySelector('#certificate-label').value.trim()||cert.name.slice(0,80)});model.certificate=result.name;data.certificates=result.certificates;wizard(false);actions.notify(result.message);actions.dirty(true)})}}
function change(event){if(!model)return;const name=event.target.name;const previousTls=model.tls_mode;const previousPortal=endpoint(model);const portalBase=previousPortal.replace(/\/RDWeb\/(?:webclient\/)?$/,'');const advancedOpen=!!view.querySelector('.advanced-options[open]');capture();if(name==='sni_domains')model.domains=String(model.sni_domains||'').split(/[\s,;]+/).filter(Boolean);actions.dirty(true);if(name==='sni_routing'&&!model.sni_routing&&['rdgateway','rdweb'].includes(model.protocol))model.redirect=false;if(['rdgateway','rdweb'].includes(model.protocol)&&model.redirect&&(name==='redirect'||['rdweb_client','sni_domains','port'].includes(name)&&(!model.http_redirect_location||model.http_redirect_location===previousPortal||model.http_redirect_location===portalBase+'/RDWeb/'||model.http_redirect_location===portalBase+'/RDWeb/webclient/'))){model.http_redirect_location=endpoint(model);if(name==='redirect')model.redirect_code=302}if(name==='replacement_id'){model.replacement_confirm=false;wizard(false);return}if(name==='protocol'){const old=model;model={...defaults(old.protocol),name:old.name,id:old.id,enabled:old.enabled,domain:old.domain||(old.domains||[])[0]||String(old.sni_domains||'').split(/[\s,;]+/)[0]||'',...(old.protocol==='studio'?{backends:defaults('studio').backends}:{}),backends:old.protocol==='studio'?defaults('studio').backends:old.backends.map(b=>({...b,port:preset().backend_port}))};wizard(false)}else if(name==='http_action'){if(model.http_action==='redirect'){model.upstream_tls=false;model.proxy_protocol=false;model.routes=[];model.health='none'}else if(!model.backends.length)model.backends=[{host:'',port:80,weight:1,backup:false}];wizard(false)}else if(name==='tls_mode'){const ports={smtps:25,imaps:143,pop3s:110,tls:80};model.backends=model.backends.map(b=>({...b,port:model.tls_mode==='terminate'&&Number(b.port)===preset().backend_port?ports[model.protocol]||b.port:previousTls==='terminate'&&model.tls_mode==='passthrough'&&Number(b.port)===ports[model.protocol]?preset().backend_port:b.port}));wizard(false)}else if(['redirect','upstream_tls','upstream_sni','health','sni_routing','rds_mode','cookie_name','health_tls_verify'].includes(name))wizard(false);if(advancedOpen&&view.querySelector('.advanced-options'))view.querySelector('.advanced-options').open=true;if(['protocol','tls_mode','http_action','redirect','upstream_tls','upstream_sni','health','sni_routing','rds_mode','cookie_name','health_tls_verify'].includes(name)&&view.querySelector('[name="'+name+'"]'))view.querySelector('[name="'+name+'"]').focus()}

function remoteHttpsNotice(){if(!['rdgateway','rdweb'].includes(model.protocol))return '';const gateway=model.protocol==='rdgateway';return `<div class="protocol-description"><strong>${gateway?'Шлюз RDP через HTTPS · TCP/443':'Веб-портал RDS · HTTPS '+rdwebPath(model)}</strong><p>Сквозной TLS: сертификат установлен на Windows и покрывает публичный домен. HAProxy передаёт соединение без изменения HTTP, RPC и авторизации. Дополнительный TLS и PROXY protocol до Windows не включаются.</p><p>${gateway?'В клиенте удалённого рабочего стола укажите этот домен как RD Gateway. UDP/3391 отдельно настраивается через NAT или UDP-балансировщик; этот шаблон передаёт только TCP. Для нескольких шлюзов по умолчанию сохраняется выбор сервера по IP клиента.':'Откройте https://ваш-домен'+rdwebPath(model)+'. IIS должен обслуживать этот путь. Для подключения к рабочим столам извне нужна также роль RD Gateway; один портал её не заменяет.'}</p><p>На общем TCP/SNI-входе 443 клиент должен отправлять SNI. Клиентам без SNI нужен отдельный IP/порт или явно согласованный fallback. Если Gateway и RD Web используют один домен и один сервер, создайте одну публикацию RD Gateway: она передаст и запросы /RDWeb/.</p></div>`}
function rdsNotice(){return `<div class="protocol-description"><strong>${model.rds_mode==='token'?'Маршрутизация по токену Connection Broker':'Вход через брокер / redirector'}</strong><p>${model.rds_mode==='token'?'На Windows должен быть включён token redirection и отключён IP address redirection. Добавьте реальные IPv4 и RDP-порты всех Session Host, куда брокер может направить клиента. HAProxy читает токен msts и выбирает указанный сервер; первое подключение без токена распределяется по выбранному алгоритму.':'Укажите серверы, принимающие RDP-подключения от имени фермы. Установка одной роли Connection Broker не гарантирует наличие RDP-входа для коллекции. При IP-перенаправлении клиент должен иметь доступ к Session Host; для внешнего доступа без такого маршрута используйте RD Gateway или токенный режим.'}</p><p>Подключайтесь RDP-файлом нужной коллекции из RD Web: поле loadbalanceinfo сохраняется без изменения. Сертификат RDP и NLA обслуживает Windows. Проверка TCP подтверждает только доступность порта. UDP этой публикацией не передаётся.</p></div>`}
function rdsFields(){return model.protocol==='rds'?select('rds_mode','Схема RDS',model.rds_mode||'broker',[['broker','На RDP-вход брокера / redirector'],['token','На Session Host по токену брокера (msts)']])+rdsNotice():''}
function enterpriseDefaults(protocol){const exchange=protocol==='exchange';return {aliases:'',certificates:[],sni_routing:false,sni_domains:'',sni_default:false,path_ignore_case:exchange,root_redirect:exchange?'/owa':'',http_exceptions:'',security_headers:exchange,health_status:exchange?'200':'2xx3xx',health_method:'GET',smtp_ehlo:'haproxy-check',health_log:exchange,check_rise:2,check_fall:3,...(exchange?{upstream_tls:true,health:'http',health_path:'/owa/healthcheck.htm',timeout:3600}:{}),routes:exchange?['/owa','/Autodiscover','/mapi','/Microsoft-Server-ActiveSync','/ews','/rpc','/ecp','/oab'].map(path=>({path,action:path==='/ecp'?'deny':'backend',health_path:path.toLowerCase()+'/healthcheck.htm',health_status:'200',timeout:3600,balance:'roundrobin',backends:[],inherit_pool:true})):[]}}
function listValue(value){return Array.isArray(value)?value.join('\n'):value||''}
function textarea(name,label,value,help=''){return `<div class="field"><label for="service-${name}">${label}</label><textarea id="service-${name}" name="${name}" rows="3">${esc(listValue(value))}</textarea><span class="field-help">${help}</span></div>`}
function domainFields(){return web()?textarea('aliases','Дополнительные домены этого сервиса',model.aliases,'По одному имени в строке: например autodiscover.example.org. Они будут использовать те же маршруты и серверы; сертификаты должны покрывать все имена.'):''}
function sniFields(){if(!['smtps','imaps','pop3s','tls','rdgateway','rdweb'].includes(model.protocol))return '';return toggle('sni_routing','Разделять общий TLS-порт по имени сервера (SNI)',model.sni_routing,'Позволяет направлять разные домены с общего TCP/TLS-входа к нужным серверам. Клиент должен отправлять SNI. Для выделенного IP/порта можно выключить.')+(model.sni_routing?textarea('sni_domains','Домены SNI этой публикации',model.domains||model.sni_domains,['rdgateway','rdweb'].includes(model.protocol)?'Публичное имя, например rdg.example.org или rdweb.example.org. Сертификат на Windows должен покрывать это имя.':'По одному имени в строке, например mail.example.org. SNI не читает адрес получателя письма.')+toggle('sni_default','Использовать этот сервис для клиентов без подходящего SNI',model.sni_default,'На одном общем порту допускается один сервер по умолчанию. Если его нет, клиент без подходящего SNI не подключится.'):'')}
function extraCertificates(){return `<div class="field"><label for="service-certificates">Дополнительные сертификаты для доменов</label><select id="service-certificates" name="certificates" multiple size="3">${data.certificates.filter(c=>c.name!==model.certificate).map(c=>`<option value="${esc(c.name)}"${(model.certificates||[]).includes(c.name)?' selected':''}>${esc(c.label||c.name)}</option>`).join('')}</select><span class="field-help">Нужны, если один основной сертификат не покрывает все домены. На компьютере выбирайте несколько с Ctrl/Cmd; на телефоне используйте список выбора.</span></div>`}
function webRoutingFields(){if(model.protocol==='rdwebproxy')return '<div class="wizard-section"><h3>Переход к порталу</h3><p>Корень / → '+esc(rdwebPath(model))+' · код 302. Выберите обычный портал или HTML5 на первом шаге. Сертификат принимает HAProxy; все остальные пути передаются внутреннему серверу.</p></div>';return `<div class="wizard-section"><h3>Домены и пути приложения</h3>${control('root_redirect','Куда перенаправлять корень сайта /',model.root_redirect||'','placeholder="Не перенаправлять"','Например /owa или https://mail.example.org/owa. Остальные пути не перенаправляются.')}${toggle('path_ignore_case','Не учитывать регистр путей',model.path_ignore_case,'Полезно для Exchange: /Autodiscover и /autodiscover будут работать одинаково.')}${toggle('security_headers','Добавить X-Frame-Options SAMEORIGIN и X-Content-Type-Options nosniff',model.security_headers)}${model.redirect?textarea('http_exceptions','Пути, которые должны работать по HTTP без перенаправления',model.http_exceptions,'Например /test или /.well-known/acme-challenge. Эти пути передаются тому же внутреннему серверу.'):''}<h3>Отдельные маршруты и проверки служб</h3><p class="field-help">Каждому пути можно назначить отдельный пул серверов и healthcheck. Пустой список серверов означает общий пул. Более длинный путь имеет приоритет; запрещённый путь отвечает 403.</p><div class="enterprise-routes">${(model.routes||[]).map((row,i)=>routeFields(row,i)).join('')}</div><button type="button" data-service-action="add-route">Добавить путь</button></div>`}
function routeFields(row,i){const base='route-'+i;const pool=row.inherit_pool!==false?'':(row.backends||[]).map(b=>(b.host.includes(':')?'['+b.host+']':b.host)+':'+b.port).join('\n');return `<details class="route-detail"${row.path?'':' open'}><summary>${esc(row.path||'Новый путь')} · ${row.action==='deny'?'Закрыт (403)':'Опубликован'}</summary><fieldset class="backend-row" data-route-row><legend>Маршрут ${i+1}</legend><div class="form-grid"><div class="field"><label for="${base}-path">Путь</label><input id="${base}-path" data-route-path value="${esc(row.path)}" required placeholder="/owa"></div><div class="field"><label for="${base}-match">Сопоставление пути</label><select id="${base}-match" data-route-match><option value="segment"${selected(row.match||'segment','segment')}>Путь и подпути</option><option value="prefix"${selected(row.match,'prefix')}>Префикс — как в старом конфиге</option></select></div><div class="field"><label for="${base}-action">Действие</label><select id="${base}-action" data-route-action><option value="backend"${selected(row.action,'backend')}>Опубликовать</option><option value="deny"${selected(row.action,'deny')}>Закрыть: ответ 403</option></select></div><div class="field"><label for="${base}-health">Страница проверки</label><input id="${base}-health" data-route-health value="${esc(row.health_path||'/')}" required></div><div class="field"><label for="${base}-status">Успешный HTTP-код</label><input id="${base}-status" data-route-status value="${esc(row.health_status||'200')}" placeholder="200 или 2xx3xx" required></div><div class="field"><label for="${base}-timeout">Таймаут, секунд</label><input id="${base}-timeout" data-route-timeout type="number" min="5" max="86400" value="${esc(row.timeout||3600)}" required></div><div class="field"><label for="${base}-balance">Распределение</label><select id="${base}-balance" data-route-balance>${[['roundrobin','По очереди'],['leastconn','Меньше соединений'],['source','По IP клиента']].map(([k,v])=>`<option value="${k}"${selected(row.balance||'roundrobin',k)}>${v}</option>`).join('')}</select></div></div><div class="field"><label for="${base}-backend-name">Имя backend этого пути</label><input id="${base}-backend-name" data-route-backend-name maxlength="63" value="${esc(row.backend_name||'')}" placeholder="be_exchange__owa"></div><div class="field"><label for="${base}-pool">Серверы только для этого пути — IP:порт</label><textarea id="${base}-pool" data-route-pool rows="2" placeholder="Пусто — использовать общий пул">${esc(pool)}</textarea></div><button type="button" data-service-action="remove-route" data-index="${i}">Убрать маршрут ${i+1}</button></fieldset></details>`}
function captureRoutes(form){if(!form.querySelector('.enterprise-routes'))return;model.routes=[...form.querySelectorAll('[data-route-row]')].map(row=>{const pool=row.querySelector('[data-route-pool]').value.trim();const old=(model.routes||[]).find(r=>r.path===row.querySelector('[data-route-path]').value)||{};return {...old,backend_name:row.querySelector('[data-route-backend-name]')?row.querySelector('[data-route-backend-name]').value:old.backend_name||'',path:row.querySelector('[data-route-path]').value,match:row.querySelector('[data-route-match]')?.value||'segment',action:row.querySelector('[data-route-action]').value,health_path:row.querySelector('[data-route-health]').value,health_status:row.querySelector('[data-route-status]').value,timeout:row.querySelector('[data-route-timeout]').value,balance:row.querySelector('[data-route-balance]').value,inherit_pool:!pool,backends:pool?pool.split(/[\s,;]+/).filter(Boolean).map(item=>{const colon=item.lastIndexOf(':');const host=item.slice(0,colon).replace(/^\[|\]$/g,''),port=item.slice(colon+1),existing=(old.backends||[]).find(s=>s.host===host&&String(s.port)===port)||{};return {...existing,host:item.slice(0,colon).replace(/^\[|\]$/g,''),port:item.slice(colon+1),weight:existing.weight||1,backup:existing.backup||false}}):[]}})}
function healthFields(){return `${web()?control('health_status','Успешный HTTP-код',model.health_status||'2xx3xx','placeholder="200 или 2xx3xx"')+select('health_method','Метод HTTP-проверки',model.health_method||'GET',[['GET','GET'],['HEAD','HEAD'],['OPTIONS','OPTIONS']]):''}${['smtp','submission','smtps'].includes(model.protocol)?control('smtp_ehlo','Имя EHLO для проверки SMTP',model.smtp_ehlo||'haproxy-check'):''}<div class="form-grid">${control('check_rise','Успешных проверок для включения',model.check_rise||2,'type="number" min="1" max="20"')}${control('check_fall','Неудачных проверок для отключения',model.check_fall||3,'type="number" min="1" max="20"')}</div>${toggle('health_log','Записывать изменения доступности в журнал HAProxy',model.health_log)}`}
function enterpriseSummary(){const domains=web()?[model.domain,...(Array.isArray(model.aliases)?model.aliases:String(model.aliases||'').split(/[\s,;]+/))]:model.sni_routing?(model.domains||String(model.sni_domains||'').split(/[\s,;]+/)):[];return domains.filter(Boolean).length>1||model.sni_routing||model.routes?.length?`<p class="field-help">${model.sni_routing?'SNI: ':'Домены: '}${esc(domains.filter(Boolean).join(', '))}${model.routes?.length?' · Маршрутов: '+model.routes.length:''}. ${model.root_redirect?'Корень сайта → '+esc(model.root_redirect):''}</p>`:''}

function mount(element,catalog,callbacks){view=element;data=catalog;actions=callbacks;model=null;step=0;list();view.onclick=handleClick;view.onchange=change;view.oninput=event=>{if(model){if(event.target.name==='backend_name'||event.target.matches('[data-server-name],[data-route-backend-name]')){model.naming='readable';const choice=view.querySelector('[name=naming]');if(choice)choice.value='readable'}actions.dirty(true)}};view.onsubmit=event=>{if(event.target.id!=='service-form')return;event.preventDefault();capture();if(!valid())return;if(step<2){step++;wizard();return}const button=event.submitter;run(button,async()=>{if(model.replacement_id&&!model.replacement_confirm)throw Error('Подтвердите замену выбранной публикации.');actions.review(await actions.api(model.replacement_id?'services/replace/preview':'services/preview',{revision:data.revision,service:model,target_id:model.replacement_id,confirm:!!model.replacement_confirm,keep_redirect:model.replacement_keep_redirect!==false}))})}}
window.StudioServices={mount,edit:id=>{const entry=data?.services?.find(s=>s.id===id);if(!entry)return;model=clone(entry);step=0;wizard()}};
})();
